# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: `ds ui` commands for delulu-smash (the services/ui Reflex app, kept running by the
#          delulu-smash.service systemd user service): the one place that knows how the app
#          runs. The Omarchy window (SUPER+SHIFT+J) is .os/scripts/keybindings/delulu-smash.py,
#          which calls `status` and `restart` here.
#
# Example CLI Commands:
#   1. The server in the foreground (what the service runs):  ds ui run
#   2. Restart, eg after changing dependencies:              ds ui restart
#   3. Is it up?                                              ds ui status
#   4. What just happened in it (its session log):            ds ui debug
# ---------------------------------------------------------------------------
from __future__ import annotations

import os
import time
import urllib.request
from http import HTTPStatus
from typing import Annotated

import typer
from ds.cli import ui_debug
from ds.cli.util import run_cmd
from ds.util.const import REPO_DIR

__all__ = ["ui_app"]


ui_app = typer.Typer(help="Run delulu-smash (the services/ui Reflex app)")

APP_NAME = "delulu-smash"
APP_DIR = REPO_DIR / "services" / "ui"
APP_SERVICE = "delulu-smash.service"
FRONTEND_URL = "http://localhost:3000"
BACKEND_PING = "http://127.0.0.1:8000/ping"
# A cold `reflex run` (frontend build + dev server) takes about a minute.
APP_START_TIMEOUT_S = 150


def _up(url: str) -> bool:
    try:
        with urllib.request.urlopen(url, timeout=2) as response:  # noqa: S310  # fixed localhost URLs
            return response.status < HTTPStatus.INTERNAL_SERVER_ERROR
    except OSError:
        return False


def ready() -> bool:
    """Both halves of the Reflex app answer: the page and the backend it talks to."""
    return _up(FRONTEND_URL) and _up(BACKEND_PING)


@ui_app.command("run")
def run() -> None:
    """Run the Reflex dev server in the foreground (what delulu-smash.service runs)

    Stop the service first to run it by hand: both use ports 3000 and 8000.
    """
    os.chdir(APP_DIR)
    os.execvp("uv", ["uv", "run", "reflex", "run"])  # noqa: S606  # fixed command, uv from PATH


@ui_app.command("restart")
def restart() -> None:
    """Restart delulu-smash (its service; starts it when stopped) and wait until it answers

    Its server reads stored keys once at start; `ds settings sync` runs this itself.
    """
    run_cmd(["systemctl", "--user", "restart", APP_SERVICE])
    typer.echo(f"Waiting for {APP_NAME} to answer (up to about a minute)...")
    deadline = time.monotonic() + APP_START_TIMEOUT_S
    while not ready():
        if time.monotonic() > deadline:
            typer.echo(f"{APP_NAME} didn't come up. Logs: journalctl --user -u {APP_SERVICE}", err=True)
            raise typer.Exit(1)
        time.sleep(1)
    typer.echo(f"{APP_NAME} is up: {FRONTEND_URL}")


@ui_app.command("status")
def status() -> None:
    """Say whether delulu-smash is answering (exit code 1 when it isn't)"""
    up = ready()
    typer.echo("up" if up else "down")
    raise typer.Exit(0 if up else 1)


@ui_app.command("debug")
def debug(
    session: Annotated[str, typer.Option(help="A session's id (see --list); the newest when left out.")] = "",
    turn: Annotated[int, typer.Option(help="Only this chat turn (turn-<n>), with every field in full.")] = 0,
    since: Annotated[str, typer.Option(help="Every session, from this long ago: 30m, 2h, 1d.")] = "",
    list_: Annotated[bool, typer.Option("--list", help="The sessions in the log, the newest last.")] = False,
    full: Annotated[bool, typer.Option("--full", help="Every field in full under each row.")] = False,
) -> None:
    """Show what just happened in delulu-smash, from its session log (local/logs/ui/ui.jsonl)

    A row per thing the user saw (chat rows, cell runs, errors), with the calls made for it
    indented under it. What to run first when debugging something that happened in the app.
    """
    try:
        start = ui_debug.parse_since(since) if since else None
    except ValueError as error:
        typer.echo(str(error), err=True)
        raise typer.Exit(2) from error
    records = ui_debug.read_records(since=start)
    if list_:
        lines = ui_debug.list_sessions(records) or ["No sessions in the log."]
    else:
        lines = ui_debug.report(records, session, turn, full=full, every=bool(since) and not session)
    typer.echo("\n".join(lines))
